            <a class="button" href="#how">Explore the pathway</a>
          </article>
          <article class="path-card path-card--child" id="children">
            <span class="icon">
              <svg viewBox="0 0 32 32" role="img" aria-label="Child health pathway icon" xmlns="http://www.w3.org/2000/svg"><circle cx="16" cy="11" r="5" fill="none" stroke="#0F4C3A" stroke-width="2.3"/><path d="M6.5 27c.7-6.1 4-9.1 9.5-9.1s8.8 3 9.5 9.1" fill="none" stroke="#0F4C3A" stroke-width="2.3" stroke-linecap="round"/><path d="M11 12h.1M21 12h.1" stroke="#0F4C3A" stroke-width="2.5" stroke-linecap="round"/></svg>
